const now = new Date();
const kstNow = new Date(now.getTime() + 9*60*60*1000);
const todayStr = kstNow.toISOString().slice(0,10);

const events = [
  {
    projectName: '○○○ 아파트',
    eventType: '그랜드오프닝',
    eventDate: '2025-04-01',
    location: '서울시 강남구 견본주택',
    contact: '02-1234-5678',
    recipients: [
      { name: '홍길동', phone: '01012345678', kakaoId: 'kakao001', channel: 'both' },
      { name: '김영희', phone: '01087654321', kakaoId: 'kakao002', channel: 'sms' }
    ]
  }
];

const results = [];
for (const event of events) {
  const eventDate = new Date(event.eventDate + 'T00:00:00+09:00');
  const todayDate = new Date(todayStr + 'T00:00:00+09:00');
  const diffDays = Math.round((eventDate - todayDate) / (1000*60*60*24));
  let sendTier = null;
  if ((event.eventType === '그랜드오프닝' || event.eventType === '견본주택') && diffDays === 3) sendTier = '1차';
  if (event.eventType === '상담안내' && diffDays === 7) sendTier = '2차';
  if (event.eventType === '청약' && diffDays === 0) sendTier = '3차';
  if (sendTier) results.push({ ...event, sendTier: sendTier, today: todayStr });
}

return results.map(function(r) { return { json: r }; });

